{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest analogue (Morgan 0.3243) is a fluorinated morpholino-heteroarene that reached 2.8 SUV in rat brain by dynamic PET, directly demonstrating good CNS penetration despite a similar polar morpholine/heteroaromatic framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943, a morpholine-containing heteroaromatic with a fluorophenyl group, showed favorable brain uptake and specific binding in rodent autoradiography/PET, supporting CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A morpholino-anilino-pyrimidine analogue achieved a 100% brain/plasma ratio, indicating that morpholine-substituted heteroaromatics can have excellent brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A lower-similarity analogue with an amide and pyrrolidine had a brain/blood ratio of 0.07, but these polar/amide features are not present in the query, limiting transfer of this poor-penetration result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Peposertib, a morpholine-containing kinase inhibitor, showed Kp,uu,brain of 5%, but its chiral alcohol and known efflux liability are structural features absent from the query, so this restricted-CNS result is only weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the highest-similarity analogue is directly brain-penetrant by PET, and multiple morpholine/heteroaromatic analogues show good CNS access; the poor-penetration analogues carry distinct polar/efflux liabilities (amide, alcohol, acid, sulfonamide) not shared by the query.",
  "evidence_gaps": [
    "No direct brain/plasma or Kp,uu measurement for the query; all evidence is from analogues with Morgan similarity <0.33.",
    "Efflux-transporter status (P-gp/BCRP) of the query is unknown; contradictory analogues suggest possible transporter liability.",
    "The query's imine/amidine and two morpholine groups may alter passive permeability relative to the closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

